# Generated by Flow (DevOps Engineer)
import subprocess
import time
from typing import Dict, List
from .interface import ContainerRuntime, ContainerResult
from ..exceptions import ContainerExecutionError

class PodmanRuntime(ContainerRuntime):
    """
    Podman implementation using the CLI wrapper. 
    Podman is often daemonless, making CLI interaction more reliable than the API in rootless mode.
    """
    def check_health(self) -> bool:
        try:
            subprocess.run(["podman", "info"], capture_output=True, check=True)
            return True
        except:
            return False

    def run_command(
        self, 
        image: str, 
        command: List[str], 
        env: Dict[str, str] = None, 
        volumes: Dict[str, str] = None, 
        cpu_limit: float = 1.0, 
        mem_limit: str = "512m", 
        timeout: int = 300
    ) -> ContainerResult:
        start_time = time.perf_counter()
        
        # Build Podman CLI arguments
        cmd = ["podman", "run", "--rm"]
        
        if env:
            for k, v in env.items():
                cmd.extend(["-e", f"{k}={v}"])
        
        if volumes:
            for src, dst in volumes.items():
                cmd.extend(["-v", f"{src}:{dst}"])
        
        cmd.extend(["--cpus", str(cpu_limit), "--memory", mem_limit])
        cmd.extend([image] + command)

        try:
            process = subprocess.run(
                cmd, 
                capture_output=True, 
                text=True, 
                timeout=timeout
            )
            
            return ContainerResult(
                exit_code=process.returncode,
                stdout=process.stdout,
                stderr=process.stderr,
                duration_ms=(time.perf_counter() - start_time) * 1000,
                runtime_used="podman"
            )
        except subprocess.TimeoutExpired:
            raise ContainerExecutionError(f"Podman execution exceeded timeout of {timeout}s")
        except Exception as e:
            raise ContainerExecutionError(f"Podman runtime failure: {e}")